"""Offline real-receipt replay + explicitly mutated adversarial cases."""
import base64, copy, json, unittest, zlib
from holder_history_sources import decode_amm_transaction
BONK = 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263'
WALLET = '2DY9qRzsHno1ekKtffJVNPtGXNYLeJaBxCADDZQXNeMS'
# Actual finalized publicnode getTransaction receipt; see docs for provenance.
REAL = json.loads(zlib.decompress(base64.b64decode('')))
SIG = REAL['transaction']['signatures'][0]
class DecoderTests(unittest.TestCase):
    def test_real_sale(self):
        out = decode_amm_transaction(REAL, SIG, BONK, WALLET)
        self.assertTrue(out['trades'], out)
        sale = next(x for x in out['trades'] if x['protocol'] == 'raydium-amm')
        self.assertEqual(sale['side'], 'sell')
        self.assertEqual(sale['tokenAmountRaw'], '84756946500')
        self.assertEqual(sale['quoteAmountRaw'], '24689852')
        self.assertEqual(sale['quoteUnit'], 'WSOL')
        self.assertIsNone(sale['usdAmount'])
    def test_wrong_wallet(self):
        self.assertEqual(decode_amm_transaction(REAL,SIG,BONK,BONK)['trades'], [])
    def test_failure(self):
        t=copy.deepcopy(REAL);t['meta']['err']={'InstructionError':[0,'x']}
        self.assertEqual(decode_amm_transaction(t,SIG,BONK,WALLET)['trades'], [])
    def test_caught_failure(self):
        t=copy.deepcopy(REAL);t['meta']['logMessages'].append('Program x failed: custom')
        self.assertEqual(decode_amm_transaction(t,SIG,BONK,WALLET)['trades'], [])
    def test_truncated_logs(self):
        t=copy.deepcopy(REAL);t['meta']['logMessages'].pop()
        self.assertEqual(decode_amm_transaction(t,SIG,BONK,WALLET)['trades'], [])
    def test_malformed_signature_list_is_coverage(self):
        for transaction in ({'signatures':[]},{'signatures':None},None,[],{}):
            with self.subTest(transaction=transaction):
                t=copy.deepcopy(REAL);t['transaction']=transaction
                out=decode_amm_transaction(t,SIG,BONK,WALLET)
                self.assertEqual(out['trades'],[])
                self.assertTrue(out['gaps'])

    def test_wrong_signature(self):
        with self.assertRaises(ValueError):decode_amm_transaction(REAL,'1'*64,BONK,WALLET)
    def test_real_bonk_buy(self):
        t=json.loads(zlib.decompress(base64.b64decode('')))
        out=decode_amm_transaction(t,t['transaction']['signatures'][0],BONK,'Fw6Tgm8uCKb35GPwsjhKv6LTFq3m6L1U35hHPYR8Ai3C')
        self.assertEqual(len(out['trades']),1)
        self.assertEqual(out['trades'][0]['side'],'buy')
        self.assertEqual(out['trades'][0]['tokenAmount'],'3469.30646')
        self.assertEqual(out['trades'][0]['quoteAmount'],'0.000102012')
    def test_orca_fill_and_distinct_ids(self):
        rows=decode_amm_transaction(REAL,SIG,BONK,WALLET)['trades']
        self.assertEqual(len(rows),2)
        self.assertEqual(len({x['id'] for x in rows}),2)
        self.assertEqual(rows[0]['protocol'],'orca-whirlpool')
        self.assertEqual(rows[0]['tokenAmountRaw'],'121025187618')
    def test_no_signer_no_trade(self):
        t=copy.deepcopy(REAL)
        for k in t['transaction']['message']['accountKeys']:k['signer']=False
        self.assertEqual(decode_amm_transaction(t,SIG,BONK,WALLET)['trades'],[])
    def test_wrong_mint(self):
        self.assertEqual(decode_amm_transaction(REAL,SIG,WALLET,WALLET)['trades'],[])
    def test_wrong_transfer_amount(self):
        t=copy.deepcopy(REAL)
        t['meta']['innerInstructions'][1]['instructions'][12]['parsed']['info']['amount']='1'
        out=decode_amm_transaction(t,SIG,BONK,WALLET)
        self.assertEqual(out['trades'],[]);self.assertTrue(out['gaps'])
    def test_transfers_without_swap(self):
        t=copy.deepcopy(REAL)
        for g in t['meta']['innerInstructions']:
            for ix in g['instructions']:
                if ix.get('programId') in ('675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8','whirLbMiicVdio4qvUfM5KAg6Ct8VwpYzGff3uctyCc'):
                    ix['data']='1'
        self.assertEqual(decode_amm_transaction(t,SIG,BONK,WALLET)['trades'],[])
    def test_collector_replay_and_null_cursor(self):
        from holder_history_sources import wallet_history
        def transport(url,payload):
            if payload['method']=='getSignaturesForAddress':data=[{'signature':SIG,'err':None}]
            else:data=REAL
            return json.dumps({'result':data}).encode(),200,{}
        out=wallet_history(BONK,WALLET,transport=transport)
        self.assertEqual(len(out['trades']),2)
        self.assertEqual(out['coverage']['nextBefore'],SIG)
        self.assertFalse(out['coverage']['complete'])
        def unavailable(url,payload):
            data=[{'signature':SIG,'err':None}] if payload['method']=='getSignaturesForAddress' else None
            return json.dumps({'result':data}).encode(),200,{}
        out=wallet_history(BONK,WALLET,transport=unavailable)
        self.assertIsNone(out['coverage']['nextBefore'])
        self.assertTrue(out['coverage']['gaps'])
if __name__ == '__main__': unittest.main()
